#pragma once
inline void runPhrase524Checks(){
 using namespace MidiTools522;
 auto require=[](bool ok,const char* message){if(!ok)throw std::runtime_error(message);};
 auto phraseNotes=[](const SequenceClip& clip,int part){std::vector<SequenceNote> result;double start=clip.loopStart+part*4;for(auto n:clip.notes)if(n.beat>=start&&n.beat<start+4){n.beat-=start;result.push_back(n);}return result;};
 auto equal=[](const std::vector<SequenceNote>& a,const std::vector<SequenceNote>& b){if(a.size()!=b.size())return false;for(int i=0;i<(int)a.size();++i)if(std::abs(a[i].beat-b[i].beat)>1e-8||std::abs(a[i].length-b[i].length)>1e-8||a[i].pitch!=b[i].pitch||a[i].velocity!=b[i].velocity)return false;return true;};
 auto occupied=[](const std::vector<SequenceNote>& notes){double sum=0;for(auto n:notes)sum+=n.length;return sum;};
 auto mono=[&](const SequenceClip& clip){auto notes=clip.notes;std::sort(notes.begin(),notes.end(),[](auto a,auto b){return a.beat<b.beat;});for(int i=0;i<(int)notes.size();++i){require(notes[i].beat>=clip.loopStart&&notes[i].beat+notes[i].length<=clip.loopEnd()+1e-7,"A/B notes within loop");if(i)require(notes[i-1].beat+notes[i-1].length<=notes[i].beat+1e-7,"A/B stays mono");}};
 SequenceClip clip;clip.setLoop(2,18);State s;s.enabled.fill(true);s.main.fill(50);s.fill.fill(50);s.values["density"]=62;s.values["rootAmount"]=38;s.values["firstRoot"]=84;s.values["gateRandom"]=25;s.values["velocityRandom"]=35;s.values["mainHigh"]=1;s.values["slop"]=20;
 auto repeated=run(clip,s,Action::generate);auto a=phraseNotes(repeated,0);require(!a.empty(),"nonempty phrase fixture");for(int part=1;part<4;++part)require(equal(a,phraseNotes(repeated,part)),"root, gate, velocity and octave decisions shared at neutral variation");
 auto neutral=run(repeated,s,Action::vary);for(int part=0;part<4;++part)require(equal(a,phraseNotes(neutral,part)),"Vary neutral leaves identical phrases");
 s.values["rhythmVariation"]=100;s.values["pitchVariation"]=100;auto alternating=run(neutral,s,Action::refresh);require(equal(a,phraseNotes(alternating,0))&&equal(a,phraseNotes(alternating,2)),"variation preserves every A");auto b=phraseNotes(alternating,1);require(equal(b,phraseNotes(alternating,3))&&!equal(a,b),"A B A B shares a different B");bool changed=false;for(int attempt=0;attempt<8;++attempt){auto varied=run(alternating,s,Action::vary);require(equal(a,phraseNotes(varied,0))&&equal(a,phraseNotes(varied,2)),"Vary keeps base A including random gates");require(equal(phraseNotes(varied,1),phraseNotes(varied,3)),"Vary preserves shared B");changed|=!equal(b,phraseNotes(varied,1));}require(changed,"Vary supplies a new B iteration");
 s.values["rhythmVariation"]=0;s.values["pitchVariation"]=0;s.values["gateRandom"]=0;s.values["velocityRandom"]=0;s.values["gate"]=100;
 auto base=run(clip,s,Action::generate);auto baseA=phraseNotes(base,0);s.values["bDensity"]=30;auto denser=run(base,s,Action::refresh);require(equal(baseA,phraseNotes(denser,0))&&equal(baseA,phraseNotes(denser,2)),"density changes B only");require(occupied(phraseNotes(denser,1))>occupied(baseA)&&phraseNotes(denser,1).size()>baseA.size(),"B density adds occupied time and notes");mono(denser);
 s.values["bDensity"]=-30;auto sparse=run(base,s,Action::refresh);require(occupied(phraseNotes(sparse,1))<occupied(baseA),"negative B density removes occupied time");
 s.values["bDensity"]=0;s.values["density"]=100;s.values["base"]=1;s.values["duration1"]=.25;s.values["duration2"]=.5;s.values["duration3"]=2;s.values["bDuration"]=50;auto sustained=run(clip,s,Action::generate);auto sustainedA=phraseNotes(sustained,0);require(sustainedA.size()==4&&equal(sustainedA,phraseNotes(sustained,1)),"duration 50 exactly matches A");
 s.values["bDuration"]=0;auto shortB=run(sustained,s,Action::refresh);require(equal(sustainedA,phraseNotes(shortB,0))&&phraseNotes(shortB,1).size()==16,"duration 0 uses shortest selected values in B");for(auto n:phraseNotes(shortB,1))require(std::abs(n.length-.25)<1e-7,"B duration changes allocated rhythm, not Gate");mono(shortB);
 s.values["bDuration"]=100;auto longB=run(sustained,s,Action::refresh);require(phraseNotes(longB,1).size()==2,"duration 100 uses longer selected values");mono(longB);
 double shorterCount=0,longerCount=0;for(int seed=1;seed<=32;++seed){auto sample=s;sample.patternSeed=seed;sample.values["bDuration"]=25;auto shorter=run(sustained,sample,Action::refresh);shorterCount+=phraseNotes(shorter,1).size();sample.values["bDuration"]=75;auto longer=run(sustained,sample,Action::refresh);longerCount+=phraseNotes(longer,1).size();}require(shorterCount>32*sustainedA.size()&&longerCount<32*sustainedA.size(),"intermediate duration settings smoothly bias probabilities");
 s.values["bDuration"]=50;s.values["bDensity"]=0;s.values["fillAmount"]=100;auto filled=run(sustained,s,Action::refresh);require(equal(sustainedA,phraseNotes(filled,0))&&equal(sustainedA,phraseNotes(filled,2)),"final Fill does not alter earlier A phrases");mono(filled);
 auto fullRhythm=s;fullRhythm.values["fillAmount"]=0;fullRhythm.values["bDuration"]=50;fullRhythm.values["bDensity"]=0;fullRhythm.values["chance1"]=45;fullRhythm.values["rhythmVariation"]=0;auto fullPattern=run(clip,fullRhythm,Action::generate);auto fullA=phraseNotes(fullPattern,0);fullRhythm.values["rhythmVariation"]=100;bool fullChanged=false;for(int i=0;i<8;++i){auto result=run(fullPattern,fullRhythm,Action::vary);require(equal(fullA,phraseNotes(result,0)),"full density rhythm retains A");require(std::abs(occupied(fullA)-occupied(phraseNotes(result,1)))<1e-7,"rhythm retains occupied time at full density");fullChanged|=!equal(fullA,phraseNotes(result,1));mono(result);}require(fullChanged,"rhythm varies duration order even without rests");
 s.values["bDensity"]=23;s.values["bDuration"]=37;juce::XmlElement document("root");s.write(document);State recalled;recalled.read(document.getChildByName("midiTools522"));require(recalled.get("bDensity")==23&&recalled.get("bDuration")==37&&recalled.baseSeed==s.baseSeed&&recalled.patternSeed==s.patternSeed,"B controls and both seeds recalled");auto replay=run(sustained,recalled,Action::refresh);auto direct=run(sustained,s,Action::refresh);for(int part=0;part<4;++part)require(equal(phraseNotes(replay,part),phraseNotes(direct,part)),"A/B deterministic after project recall");
 SequenceClip partial;partial.setLoop(1,7);s.values["fillAmount"]=0;auto shortLast=run(partial,s,Action::generate);mono(shortLast);
 std::cout<<"524 passed: shared probabilistic A, A/B repetition, Vary preserving A, density, continuous duration bias, mono boundaries, final Fill and project recall\n";
}
